package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class RestoreInspection {
 static JSONArray selected(JSONObject doc,JSONArray selected)throws Exception{if(selected.length()==0||selected.length()>3)throw new IOException("復元対象を選んでください");JSONArray out=new JSONArray();Set<String> seen=new HashSet<>();for(int i=0;i<selected.length();i++){String key=selected.getString(i);if(!key.matches("notes|memory|settings")||!doc.has(key)||!seen.add(key))throw new IOException("復元対象が不正です");out.put(key);}return out;}
 static JSONObject inspect(Context c,JSONObject doc,JSONArray keys)throws Exception{synchronized(PersonalNotes.class){PortableBackup.validate(doc);keys=selected(doc,keys);JSONArray all=PersonalNotes.all(c);int required=0,duplicates=0,similar=0;JSONArray incoming=doc.optJSONArray("notes");if(MaintenancePolicy.selected(keys,"notes"))for(int i=0;i<incoming.length();i++){JSONObject row=incoming.getJSONObject(i);String id=PortableBackup.restoredId(doc.getString("archiveId"),row.getString("id"));boolean exists=false,match=false;for(int j=0;j<all.length();j++){JSONObject old=all.getJSONObject(j);if(id.equals(old.getString("id")))exists=true;if(old.optLong("deletedAt")==0&&RecordSearchPolicy.normalized(row.getString("text")).equals(RecordSearchPolicy.normalized(old.getString("text"))))match=true;}if(exists)duplicates++;else required++;if(match)similar++;}int live=PersonalNotes.list(c).length();long reserve=Math.max(1048576,doc.toString().getBytes("UTF-8").length*3L),free=c.getFilesDir().getUsableSpace();JSONObject before=DisplayPreferences.read(c),after=MaintenancePolicy.selected(keys,"settings")?DisplayPreferences.checked(doc.getJSONObject("settings")):before;JSONObject base=new JSONObject().put("archive",ReviewStore.hash(doc)).put("selected",keys).put("notes",all).put("display",before).put("memory",ReviewStore.hash(ReviewStore.read(c,"restored-memory")));return new JSONObject().put("revision",ReviewStore.hash(base)).put("notesToAdd",required).put("alreadyRestored",duplicates).put("sameTextCount",similar).put("activeAfter",live+required).put("allAfter",all.length()+required).put("freeBytes",free).put("requiredFreeBytes",reserve).put("capacityOk",live+required<=100&&all.length()+required<=200&&free>=reserve).put("beforeSettings",before).put("afterSettings",after).put("memoryReplacement",MaintenancePolicy.selected(keys,"memory")).put("message","同じ本文でも別アーカイブのメモは追加対象です。復元済みIDは編集・削除済みでも上書きしません。容量は安全余裕を含む事前見積りです。保存中の容量変化や書込み失敗は別途起こり得ます");}}
 static JSONObject restore(Context c,JSONObject doc,JSONArray keys,String revision)throws Exception{String lease=MaintenanceLease.acquire(c,"restore");boolean success=false;try{synchronized(PersonalNotes.class){JSONObject plan=inspect(c,doc,keys);if(!plan.getString("revision").equals(revision))throw new IOException("復元先か選択内容が変わりました。事前検査をやり直してください");if(!plan.getBoolean("capacityOk"))throw new IOException("メモ件数または空き容量が不足しています。復元していません");JSONObject result=PortableBackup.restore(c,doc,keys);success=true;return result;}}finally{MaintenanceLease.finish(c,lease,success?"COMPLETED":"FAILED");}}
 private RestoreInspection(){}
}
